def transform(grid):
    g=[row[:] for row in grid]
    R=len(g); C=len(g[0])
    cells=set((r,c) for r in range(R) for c in range(C) if g[r][c]!=0)
    if not cells: return g
    best=None; bestscore=-1
    for s in range(0,2*C-1):
        score=sum(1 for (r,c) in cells if (r,s-c) in cells)
        if score>bestscore: bestscore=score; best=('v',s)
    for s in range(0,2*R-1):
        score=sum(1 for (r,c) in cells if (s-r,c) in cells)
        if score>bestscore: bestscore=score; best=('h',s)
    typ,s=best
    for (r,c) in list(cells):
        if typ=='v':
            mc=s-c
            if 0<=mc<C: g[r][mc]=g[r][c]
        else:
            mr=s-r
            if 0<=mr<R: g[mr][c]=g[r][c]
    return g
